        for(String field:new String[]{"customer_id","name","address","district","access_notes","notes","area_decimal","area_unit","latitude","longitude","active"})if(changes.has(field))row.put(field,changes.get(field));
        String customer=id(row,"customer_id",true);customer(state,customer,creating);if(old!=null&&!old.getString("customer_id").equals(customer))throw error("PROPERTY_CUSTOMER_CHANGE_REVIEW_REQUIRED","Objektkunden nicht still wechseln. Ursprüngliche Zuordnung bleibt erhalten.");
        row.put("name",text(row,"name",240,true));for(String field:new String[]{"address","district","access_notes","notes","area_unit"})row.put(field,text(row,field,field.equals("notes")?10000:2000,false));row.put("active",bool(row,"active",true));
